Method.Implementation:
 $$$TRACE(" oldUnitNumber: " _ pRequest.oldMmi _ ", newUnitNumber: " _ pRequest.newMmi)
 try
 {
   set ejbObj=##class(org.ihc.itf.PhcWebEjb).%New(..JavaGateway)
   $$$TRACE("created object")

   set status = ejbObj.sendDataToSubscriptionService( pRequest.oldMmi,pRequest.newMmi, ..URL )
   $$$TRACE("SendData SubscriptionService: oldUnitNumber: " _  pRequest.oldMmi _ ", newUnitNumber: " _ pRequest.newMmi _ " to URL: " _ ..URL _ ", status: " _ status)

 if (status = 1)
 {
	 set status = $$$OK
 }
 } catch ex
 {
	set status = $$$ERROR("Exception in sendDataToTelepatient" _ ex.Data)
 }  
 set pResponse = status
 $$$TRACE("Response: " _ status)
  return status
